function lockLearnerApis(){for(const key of ['indexedDB','caches','fetch','XMLHttpRequest','WebSocket','EventSource','WebTransport','Worker','SharedWorker','BroadcastChannel','importScripts']){let o=self;while(o){try{const d=Object.getOwnPropertyDescriptor(o,key);if(d?.configurable)delete o[key]}catch{}o=Object.getPrototypeOf(o)}try{Object.defineProperty(self,key,{value:undefined,writable:false,configurable:false})}catch{}}}
/* Optional isolated Python runtime. Loaded only after the learner starts the workshop. */
let runtimePromise;
self.onmessage=async e=>{const {id,code}=e.data;if(typeof code!=='string'||code.length>12000){postMessage({id,error:'Le programme est trop long pour cet atelier.'});return}try{if(!runtimePromise){runtimePromise=import('./runtime/python/pyodide.mjs').then(({loadPyodide})=>loadPyodide({indexURL:new URL('./runtime/python/',self.location.href).href,stdout:text=>postMessage({id,output:String(text)}),stderr:text=>postMessage({id,output:String(text)})}))}const py=await runtimePromise;lockLearnerApis();postMessage({id,ready:true});await py.runPythonAsync(code);postMessage({id,done:true})}catch(error){const msg=String(error?.message||error);const friendly=/SyntaxError/.test(msg)?'Vérifie les parenthèses, les guillemets et les deux-points de ton programme.':/NameError/.test(msg)?'Un nom n’est pas défini. Vérifie son orthographe et sa création avant utilisation.':/IndentationError/.test(msg)?'Vérifie les espaces au début des lignes : ils organisent les blocs Python.':/ZeroDivisionError/.test(msg)?'Une division par zéro n’est pas possible. Vérifie le dénominateur.':'Relis la dernière ligne du message pour repérer le problème.';postMessage({id,error:friendly+'\n\n'+msg})}};
